  'REFERENCIA': 'Ref',
  'DATA VENCIMENTO': 'Data Vencimento',
  'VALOR PARCELA': 'INADIMPLENCIA',
  'EMAIL': 'Email'
};

// 🧩 Funções auxiliares
const normalize = str => str ? str.toString().trim().toLowerCase() : '';

const limparEndereco = texto =>
  texto ? texto.toString().replace(/[.,;:]/g, '').trim() : '';

// ✅ CPF — 11 dígitos com zeros à esquerda, forçando texto no Excel
const formatarCPF = valor => {
  if (!valor) return '="00000000000"';
  const num = valor.toString().replace(/\D/g, '').trim();
  const cpfFormatado = num.padStart(11, '0').slice(-11);
  return `="${cpfFormatado}"`; // ✅ Excel mantém os zeros como texto
};

// 📅 Data formato AAAAMMDD
const formatarData = data => {
  if (!data) return '';
  const d = new Date(data);
  if (isNaN(d)) return '';
  return `${d.getFullYear()}${String(d.getMonth() + 1).padStart(2, '0')}${String(d.getDate()).padStart(2, '0')}`;
};

// 💰 Valor — sempre duas casas decimais com vírgula
const formatarValor = valor => {
  if (valor === undefined || valor === null || valor === '') return '';
  let numStr = valor.toString().replace(/[^\d,.-]/g, '').trim();
  numStr = numStr.replace(',', '.');
  const num = parseFloat(numStr);
  if (isNaN(num)) return '';
  return num.toFixed(2).replace('.', ',');
};

// ✉️ Limpa e-mail
const limparEmail = email => email ? email.toString().replace(/['"]/g, '').trim() : '';

// 🔍 Lê dados do nó anterior
let inputData = $input.all().map(i => i.json);
if (inputData.length === 1 && Array.isArray(inputData[0].data)) {
  inputData = inputData[0].data;
}

// 🧩 Normaliza cabeçalhos
const headers = {};
if (inputData.length > 0) {
  Object.keys(inputData[0]).forEach(key => {
    headers[normalize(key)] = key;
  });
}

// 🧱 Processamento principal
const output = inputData.map(row => {
  const novo = {};

  for (const [saida, entrada] of Object.entries(map)) {
    let valor = '';
    if (entrada) {
      const match = headers[normalize(entrada)];
      valor = match ? row[match] ?? '' : '';
    }

    // Aplicar formatações específicas
    switch (saida) {
      case 'ENDEREÇO':
        valor = limparEndereco(valor);
        break;
      case 'CPF':
        valor = formatarCPF(valor);
        break;
      case 'DATA VENCIMENTO':
        valor = formatarData(valor);
        break;
      case 'VALOR PARCELA':
        valor = formatarValor(valor);
        break;
      case 'TELEFONE':
        valor = row['Telefone 1'] ?? '';
        break;
      case 'CELULAR':
        valor = row['Telefone 2'] ?? '';
        break;
      case 'EMAIL':
        valor = limparEmail(valor);
        break;
    }

    novo[saida] = valor;
  }

  // ✅ Coluna adicional "INADIMPLENCIA MENOS BOLSAS"
  const valorInadBolsas = row['INADIMPLENCIA MENOS BOLSAS CONDICIONAIS'] ?? '';
  const valorFormatado = formatarValor(valorInadBolsas);

  const ordenado = {};
  for (const key of Object.keys(novo)) {
    ordenado[key] = novo[key];
    if (key === 'EMAIL') {
      ordenado[''] = ''; // Coluna R vazia
      ordenado['INADIMPLENCIA MENOS BOLSAS'] = valorFormatado;
    }
  }

  return { json: ordenado };
});

return output;

