  if (!valor) return '="00000000000"';
  const num = valor.toString().replace(/\D/g, '').trim();
  const cpfFormatado = num.padStart(11, '0').slice(-11);
  return `="${cpfFormatado}"`;
};

// 📅 Data formato AAAAMMDD (corrigido e inteligente)
const formatarData = data => {
  if (!data) return '';

  // Se vier como número do Excel (ex: 45678)
  if (!isNaN(data) && data.toString().length < 6) {
    const base = new Date(1899, 11, 30);
    const converted = new Date(base.getTime() + (data * 86400000));
    return `${converted.getFullYear()}${String(converted.getMonth() + 1).padStart(2, '0')}${String(converted.getDate()).padStart(2, '0')}`;
  }

  // Se vier no formato dd/mm/yyyy
  if (/^\d{1,2}\/\d{1,2}\/\d{4}$/.test(data)) {
    const [dia, mes, ano] = data.split('/');
    return `${ano}${mes.padStart(2, '0')}${dia.padStart(2, '0')}`;
  }

  // Se vier no formato yyyy-mm-dd
  if (/^\d{4}-\d{2}-\d{2}$/.test(data)) {
    const [ano, mes, dia] = data.split('-');
    return `${ano}${mes}${dia}`;
  }

  // Último recurso: tentar converter com Date
  const d = new Date(data);
  if (isNaN(d)) return '';
  return `${d.getFullYear()}${String(d.getMonth() + 1).padStart(2, '0')}${String(d.getDate()).padStart(2, '0')}`;
};

// 💰 Valor — duas casas decimais com vírgula, forçando texto no Excel
const formatarValor = valor => {
  if (valor === undefined || valor === null || valor === '') return '="0,00"';
  let numStr = valor.toString().replace(/[^\d,.-]/g, '').trim();
  numStr = numStr.replace(',', '.');
  const num = parseFloat(numStr);
  if (isNaN(num)) return '="0,00"';
  return `="${num.toFixed(2).replace('.', ',')}"`;
};

// ✉️ Limpa e-mail
const limparEmail = email => email ? email.toString().replace(/['"]/g, '').trim() : '';

// ☎️ Formata telefone/celular: somente números e apenas o primeiro
const formatarTelefoneUnico = valor => {
  if (!valor) return '';
  let limpo = valor.toString().replace(/\D/g, '');
  if (limpo.length > 11) limpo = limpo.slice(0, 11);
  return limpo;
};

