        // tenta achar qualquer coluna que contenha "telefone 2"
        const tel2Key = Object.keys(headers).find(h => h.includes('telefone 2'));
        if (tel2Key) {
          valor = row[headers[tel2Key]] ?? '';
        }

        // fallback: se vier vazio, usa Telefone 1
        if (!valor) {
          const tel1Key = Object.keys(headers).find(h => h.includes('telefone 1'));
          valor = tel1Key ? row[headers[tel1Key]] ?? '' : '';
        }

        valor = formatarTelefoneUnico(valor);
        break;
      }
    }

    novo[saida] = valor;
  }

